// Simple application with improved error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ── Configuration ────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
const MAX_PAGE_SIZE = 100;

// ── Security Middleware ───────────────────────────────────────────────────────

// Set secure HTTP headers (X-Content-Type-Options, X-Frame-Options, etc.)
app.use(helmet());

// Limit request body size to prevent large-payload attacks
app.use(express.json({ limit: '10kb' }));

// Rate limiting: max 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Mock data — in production this would come from a database
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res, next) => {
  try {
    // --- Input validation for pagination query params ---
    const rawPage = req.query.page !== undefined ? Number(req.query.page) : 1;
    const rawLimit = req.query.limit !== undefined ? Number(req.query.limit) : 10;

    if (!Number.isInteger(rawPage) || rawPage < 1) {
      return res.status(400).json({ error: '`page` must be a positive integer.' });
    }

    if (!Number.isInteger(rawLimit) || rawLimit < 1 || rawLimit > MAX_PAGE_SIZE) {
      return res
        .status(400)
        .json({ error: `\`limit\` must be an integer between 1 and ${MAX_PAGE_SIZE}.` });
    }

    // Paginate results
    const start = (rawPage - 1) * rawLimit;
    const paginated = USERS.slice(start, start + rawLimit);

    res.json({
      data: paginated,
      meta: {
        page: rawPage,
        limit: rawLimit,
        total: USERS.length,
      },
    });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ── 404 Handler ───────────────────────────────────────────────────────────────
// Must be placed after all valid routes
app.use((req, res) => {
  res.status(404).json({ error: `Route ${req.method} ${req.path} not found.` });
});

// ── Global Error Handler ──────────────────────────────────────────────────────
// Must have exactly 4 arguments so Express recognises it as an error handler
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally — never expose stack traces to clients
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred.' // Hide details in production
        : err.message,                    // Expose details in development only
  });
});

// ── Server Bootstrap ──────────────────────────────────────────────────────────
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle port-in-use and permission errors gracefully
server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use.`);
  } else if (err.code === 'EACCES') {
    console.error(`Permission denied to bind on port ${PORT}.`);
  } else {
    console.error('Server error:', err);
  }
  process.exit(1);
});

module.exports = app;

