// app.improved.js — Secured and hardened version of app.js

'use strict';

const express = require('express');
const helmet = require('helmet');           // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors');               // CORS policy

const app = express();

// ─── Environment Config ───────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN || 'https://yourdomain.com';

// ─── Security Middleware ──────────────────────────────────────────────────────

// 1. Set secure HTTP headers (removes X-Powered-By, adds HSTS, etc.)
app.use(helmet());

// 2. Restrict Cross-Origin requests to a known origin
app.use(cors({
  origin: ALLOWED_ORIGIN,
  methods: ['GET'],               // Only allow what you actually use
  allowedHeaders: ['Content-Type'],
}));

// 3. Apply rate limiting to all routes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,      // 15-minute window
  max: 100,                       // Max 100 requests per window per IP
  standardHeaders: true,          // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// 4. Parse JSON bodies safely (limits payload size to prevent large-body attacks)
app.use(express.json({ limit: '10kb' }));

// ─── Routes ───────────────────────────────────────────────────────────────────

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users listing — with input validation on query params
app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?limit= query param
    const { limit } = req.query;

    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);

      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        // 400 Bad Request for invalid input — never trust client data
        return res.status(400).json({
          error: 'Invalid "limit" parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    // NOTE: In a real app, never send raw DB rows to the client.
    // Select only the fields the client needs (avoid over-fetching).
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = limit ? users.slice(0, parseInt(limit, 10)) : users;
    res.json(result);

  } catch (err) {
    // Forward unexpected errors to the global error handler
    next(err);
  }
});

// ─── 404 Handler ─────────────────────────────────────────────────────────────
// Catches requests to any undefined route
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── Global Error Handler ─────────────────────────────────────────────────────
// Must have exactly 4 arguments so Express recognises it as an error handler
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally but NEVER expose stack traces to clients
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'  // Sanitised message in production
      : err.message,                     // Detailed message in development only
  });
});

// ─── Server Bootstrap ─────────────────────────────────────────────────────────
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

