// Simple application with security best practices applied
'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ─── 1. SECURITY HEADERS ─────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, X-XSS-Protection, etc.
app.use(helmet());

// ─── 2. REQUEST LOGGING ───────────────────────────────────────────────────────
// Use 'combined' in production for full Apache-style logs; 'dev' for local dev
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ─── 3. BODY PARSING (with size limit to prevent payload flooding) ────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 4. GLOBAL RATE LIMITER ──────────────────────────────────────────────────
// Allows up to 100 requests per 15-minute window per IP
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// ─── ROUTES ──────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 5. INPUT VALIDATION on /users ───────────────────────────────────────────
// Validates query params before using them; avoids trusting raw user input.
app.get('/users', (req, res, next) => {
  try {
    const { page = '1', limit = '10' } = req.query;

    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    // Reject non-integer or out-of-range values
    if (!Number.isInteger(pageNum) || pageNum < 1) {
      return res.status(400).json({ error: 'Invalid "page" parameter. Must be a positive integer.' });
    }
    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({ error: 'Invalid "limit" parameter. Must be between 1 and 100.' });
    }

    // ── In a real app, query your database here using pageNum/limitNum ──────
    // Hardcoded data is used here for demonstration only. Never expose
    // sensitive fields (passwords, tokens, internal IDs) in responses.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const start = (pageNum - 1) * limitNum;
    const paginatedUsers = allUsers.slice(start, start + limitNum);

    res.json({
      data: paginatedUsers,
      meta: {
        page: pageNum,
        limit: limitNum,
        total: allUsers.length,
      },
    });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ─── 6. 404 HANDLER ──────────────────────────────────────────────────────────
// Catches requests to undefined routes before they hit the error handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 7. GLOBAL ERROR HANDLER ─────────────────────────────────────────────────
// Must have exactly 4 parameters for Express to treat it as an error handler.
// Prevents stack traces from leaking to clients in production.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';
  console.error(`[Error] ${err.message}`, isDev ? err.stack : '');

  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: isDev ? err.message : 'An unexpected error occurred. Please try again later.',
    ...(isDev && { stack: err.stack }), // Only expose stack trace in development
  });
});

// ─── 8. SERVER START (port from environment, not hardcoded) ──────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with security best practices",
  "main": "app.js",
  "scripts": {
    "start": "NODE_ENV=production node app.js",
    "dev": "NODE_ENV=development node app.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "express-rate-limit": "^7.1.5",
    "helmet": "^7.1.0",
    "morgan": "^1.10.0"
  }
}

