const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    Sets well-known protective HTTP headers (XSS, clickjacking, MIME, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS — only allow requests from a trusted origin
// ---------------------------------------------------------------------------
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://yourdomain.com',
  methods: ['GET'],
}));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING — mitigate brute-force and DoS attacks
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15-minute window
  max: 100,                  // max requests per IP per window
  standardHeaders: true,     // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,      // Disable deprecated `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. BODY PARSING — enforce payload size limits to prevent DoS via large bodies
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 5. REQUEST LOGGING — structured access logs for auditing and debugging
// ---------------------------------------------------------------------------
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Basic liveness check — no sensitive data exposed.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns user list. Query params are validated and sanitized before use.
 *
 * Optional query params:
 *   ?id=1          (positive integer)
 *   ?name=Alice    (alphanumeric, trimmed, HTML-escaped)
 */
app.get(
  '/users',
  [
    // 6. INPUT VALIDATION — validate and sanitize all incoming query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('id must be a positive integer')
      .toInt(),
    query('name')
      .optional()
      .isAlphanumeric()
      .withMessage('name must be alphanumeric')
      .trim()
      .escape(),
  ],
  (req, res) => {
    // Return validation errors early — never process malformed input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // NOTE: In a real application, replace this static data with a database
    //       query using parameterized statements (never string interpolation)
    //       and enforce authentication/authorization before returning records.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  }
);

// ---------------------------------------------------------------------------
// 7. 404 HANDLER — catch requests to unknown routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// ---------------------------------------------------------------------------
// 8. GLOBAL ERROR HANDLER
//    - Logs full error server-side
//    - Never leaks stack traces or internal details to clients in production
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] ERROR:`, err.stack);

  const statusCode = err.status || err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal server error' // hide details in production
      : err.message;            // surface details during development

  res.status(statusCode).json({ error: message });
});

// ---------------------------------------------------------------------------
// SERVER STARTUP
// ---------------------------------------------------------------------------
// 9. ENVIRONMENT-CONFIGURABLE PORT — never hardcode infrastructure values
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

module.exports = { app, server };

