// app.js — Improved with security best practices

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Security Middleware
// ---------------------------------------------------------------------------

// 1. Set secure HTTP headers (X-Content-Type-Options, X-Frame-Options, etc.)
app.use(helmet());

// 2. Parse JSON bodies and enforce a size limit to prevent payload flooding
app.use(express.json({ limit: '10kb' }));

// 3. Global rate limiter — 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Mock data (clearly isolated — replace with DB calls in production)
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Input validation helpers
// ---------------------------------------------------------------------------

/**
 * Returns true if `value` is a safe positive integer string.
 * Prevents type-coercion tricks and non-numeric IDs.
 */
function isPositiveIntString(value) {
  return /^\d+$/.test(value) && Number.isInteger(Number(value)) && Number(value) > 0;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — omit internal timestamps to reduce fingerprinting surface
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// List all users
app.get('/users', (req, res) => {
  res.json(USERS);
});

// Get a single user by ID — with explicit input validation
app.get('/users/:id', (req, res) => {
  const { id } = req.params;

  // Validate: must be a positive integer
  if (!isPositiveIntString(id)) {
    return res.status(400).json({ error: 'Invalid user ID. Must be a positive integer.' });
  }

  const user = USERS.find((u) => u.id === Number(id));

  if (!user) {
    return res.status(404).json({ error: 'User not found.' });
  }

  res.json(user);
});

// ---------------------------------------------------------------------------
// Catch-all 404 handler — must come after all valid routes
// ---------------------------------------------------------------------------

app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// Global error handler — must have exactly 4 arguments for Express to
// recognise it as an error-handling middleware
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging
  console.error('[Unhandled Error]', err);

  // Never leak stack traces or internal details to the client
