// Simple application - improved for security and error handling

const express = require('express');

// --- Security & utility middleware ---
// Run: npm install helmet express-rate-limit
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// 1. SECURITY HEADERS
// Removes 'X-Powered-By', sets CSP, HSTS, and other protective headers.
app.use(helmet());

// 2. REQUEST BODY PARSING with size limit to prevent payload flooding
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. RATE LIMITING
// Limits each IP to 100 requests per 15-minute window.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// --- Routes ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // 4. INPUT VALIDATION on query parameters
  const { id } = req.query;

  // Allowlist of valid query params — reject unexpected ones
  const allowedParams = ['id'];
  const receivedParams = Object.keys(req.query);
  const invalidParams = receivedParams.filter(p => !allowedParams.includes(p));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameter(s): ${invalidParams.join(', ')}`,
    });
  }

  // Validate 'id' is a positive integer if provided
  if (id !== undefined) {
    const parsedId = parseInt(id, 10);
    if (isNaN(parsedId) || parsedId <= 0 || String(parsedId) !== id) {
      return res.status(400).json({ error: 'Invalid id: must be a positive integer.' });
    }
  }

  // 5. FIELD FILTERING — only expose necessary fields (omit sensitive data)
  // In production, replace this with a real database call.
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Only return the 'id' and 'name' fields — exclude email (or other PII)
  // unless the caller is authenticated and authorized.
  const safeUsers = allUsers
    .filter(user => (id ? user.id === parseInt(id, 10) : true))
    .map(({ id, name }) => ({ id, name })); // strip email from public response

  if (id && safeUsers.length === 0) {
    return res.status(404).json({ error: 'User not found.' });
  }

  res.json(safeUsers);
});

// 6. CATCH-ALL 404 HANDLER — must be defined after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// 7. GLOBAL ERROR HANDLER — must have exactly 4 arguments for Express to recognize it
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally for debugging/auditing
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Never expose internal error details or stack traces to the client
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// 8. CONFIGURABLE PORT via environment variable with a safe default
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

