// app.js — Express application with security best practices applied

'use strict';

const express = require('express');
const helmet  = require('helmet');

const app  = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;

// ---------------------------------------------------------------------------
// Global middleware
// ---------------------------------------------------------------------------

// 1. Set secure HTTP headers (X-Content-Type-Options, X-Frame-Options, etc.)
app.use(helmet());

// 2. Parse JSON request bodies; enforce a size limit to prevent payload floods
app.use(express.json({ limit: '10kb' }));

// 3. Basic request logger (replace with a structured logger such as `pino`
//    or `winston` in production)
app.use((req, _res, next) => {
  // NOTE: never log Authorization headers, cookies, or sensitive body fields
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ---------------------------------------------------------------------------
// Input validation helpers
// ---------------------------------------------------------------------------

/**
 * Returns true only when the value is a safe, positive integer string.
 * Rejects negatives, floats, leading zeros, and non-numeric input.
 */
function isPositiveIntegerString(value) {
  return typeof value === 'string' && /^[1-9]\d{0,9}$/.test(value);
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no user input involved, keep it simple
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// List users — in a real app this would query a database
app.get('/users', (_req, res) => {
  // Static data shown here; substitute with a parameterised DB query in
  // production and never expose password hashes or internal IDs unnecessarily.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'  },
  ]);
});

// Get a single user by ID — demonstrates safe parameter validation
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate: must be a positive integer to prevent injection / path abuse
    if (!isPositiveIntegerString(id)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'User ID must be a positive integer.',
      });
    }

    const userId = parseInt(id, 10);

    // Stub — replace with a real DB lookup using a parameterised query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'  },
    ];
    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with ID ${userId}.`,
      });
    }

    return res.json(user);
  } catch (err) {
    // Delegate unexpected errors to the global error handler below
    return next(err);
  }
});

// ---------------------------------------------------------------------------
// 404 handler — must be registered AFTER all valid routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist.',
  });
});

// ---------------------------------------------------------------------------
// Global error handler — must have exactly four parameters for Express to
// recognise it as an error-handling middleware
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side for debugging
  console.error(`[ERROR] ${err.message}`, { stack: err.stack });

  // Return a sanitised message to the client — never expose stack traces
  const statusCode = Number.isInteger(err.status) ? err.status : 500;
  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// Start server (only when this file is run directly, not when imported in
// tests — prevents port conflicts during automated testing)
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

