// Simple application with security best practices applied
// Improvements: helmet, rate limiting, input validation, error handling, CORS, env-driven config

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Frame-Options, X-Content-Type-Options,
//    Content-Security-Policy, etc. automatically)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS – explicitly allow only known origins
// ---------------------------------------------------------------------------
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '')
  .split(',')
  .map((o) => o.trim())
  .filter(Boolean);

app.use(
  cors({
    origin: ALLOWED_ORIGINS.length > 0 ? ALLOWED_ORIGINS : false,
    methods: ['GET'],
    optionsSuccessStatus: 200,
  })
);

// ---------------------------------------------------------------------------
// 3. Body parsing with a strict size limit (protects against large-payload DoS)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Global rate limiter – max 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users – demonstrates input validation on an optional query parameter
// Example: GET /users?limit=5
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be an integer between 1 and 100')
      .toInt(),
  ],
  (req, res, next) => {
    // 5. Reject requests that fail validation – never trust raw input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const limit = req.query.limit ?? users.length;
      return res.json(users.slice(0, limit));
    } catch (err) {
      // Forward unexpected errors to the centralised handler
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// 6. 404 handler – catches any route that was not matched above
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 7. Centralised error handler – must have exactly 4 parameters so Express
//    recognises it as an error-handling middleware
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Avoid leaking internal details (stack traces, DB messages, etc.) to clients
  const isDev = process.env.NODE_ENV === 'development';

  console.error('[ERROR]', err); // Log the full error server-side

  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An unexpected error occurred.',
    ...(isDev && { stack: err.stack }),
  });
});

// ---------------------------------------------------------------------------
// 8. Start server only when this file is run directly (not when imported in
//    tests), and use the env-driven PORT
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

