// Simple application with security best practices applied
// Improvements: error handling, input validation, security headers, rate limiting

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets a suite of protective HTTP headers automatically.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. BODY PARSING WITH SIZE LIMITS
//    Prevents payload-based DoS attacks by capping request body size.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Limits each IP to 100 requests per 15-minute window to deter abuse.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// STATIC DATA (moved out of route handlers for separation of concerns)
// ---------------------------------------------------------------------------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

// Health check — no user input, low risk
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — supports optional ?id= query param with strict validation
app.get('/users', (req, res, next) => {
  try {
    const { id } = req.query;

    // If an `id` query parameter is provided, validate and filter
    if (id !== undefined) {
      // 4. INPUT VALIDATION: reject non-numeric or out-of-range values early
      const parsedId = parseInt(id, 10);

      if (
        isNaN(parsedId) ||        // must be a number
        String(parsedId) !== id || // must be an integer with no extra chars
        parsedId < 1              // must be a positive integer
      ) {
        // 5. SAFE ERROR RESPONSES: never leak internals; use consistent shape
        return res.status(400).json({
          error: 'Invalid input.',
          details: '`id` must be a positive integer.',
        });
      }

      const user = USERS.find((u) => u.id === parsedId);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }

      return res.json(user);
    }

    // No filter — return full list
    res.json(USERS);
  } catch (err) {
    // Pass unexpected errors to the global error handler below
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 6. 404 HANDLER — catches requests to undefined routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 7. GLOBAL ERROR HANDLER
//    Must have exactly 4 parameters so Express recognises it as error middleware.
//    Logs the full error server-side; sends a safe, generic message to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log internally for diagnostics — swap for a logger (e.g. winston/pino) in production
  console.error(`[ERROR] ${req.method} ${req.path}:`, err);

  // Never expose stack traces or internal messages to the client
  res.status(err.status || 500).json({
    error: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// 8. SERVER STARTUP — port driven by environment variable
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

