// Simple application with security best practices applied
// Improvements: error handling, input validation, security headers,
// rate limiting, logging, CORS, and environment-based config.

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets a suite of well-known HTTP headers (CSP, HSTS, etc.)
//    to protect against common web vulnerabilities out of the box.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS POLICY
//    Explicitly whitelist allowed origins instead of accepting all (*).
//    Adjust ALLOWED_ORIGIN via environment variable per deployment.
// ---------------------------------------------------------------------------
const corsOptions = {
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// ---------------------------------------------------------------------------
// 3. BODY PARSING WITH SIZE LIMITS
//    Limits prevent denial-of-service via oversized request payloads.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. RATE LIMITING
//    Restricts each IP to 100 requests per 15-minute window.
//    Adjust limits per route sensitivity (stricter on auth endpoints, etc.)
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* legacy headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 5. MINIMAL REQUEST LOGGING (no third-party logger required)
//    Logs method, path, status, and response time without exposing sensitive
//    data. Replace with a structured logger (e.g. winston/pino) in production.
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    // Avoid logging query strings verbatim — they may contain secrets.
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

// Health check — no sensitive data, no auth required.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// 6. INPUT VALIDATION on query parameters
//    Always validate and sanitize before using any request-supplied value.
//    Using allowlists (known-good values) is safer than denylists.
// ---------------------------------------------------------------------------
const VALID_SORT_FIELDS = ['id', 'name'];
const VALID_SORT_ORDERS = ['asc', 'desc'];

// Simulated data — replace with a real DB call in production.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res, next) => {
  try {
    // -- Pagination --
    const page  = parseInt(req.query.page,  10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      // 400 Bad Request — client error, not a 500.
      return res.status(400).json({ error: 'Invalid pagination parameters. page ≥ 1, 1 ≤ limit ≤ 100.' });
    }

    // -- Sorting (allowlist) --
    const sortBy    = req.query.sortBy    || 'id';
    const sortOrder = req.query.sortOrder || 'asc';

    if (!VALID_SORT_FIELDS.includes(sortBy)) {
      return res.status(400).json({ error: `Invalid sortBy field. Allowed: ${VALID_SORT_FIELDS.join(', ')}.` });
    }
    if (!VALID_SORT_ORDERS.includes(sortOrder)) {
      return res.status(400).json({ error: `Invalid sortOrder. Allowed: ${VALID_SORT_ORDERS.join(', ')}.` });
    }

    // -- Process --
    const sorted = [...USERS].sort((a, b) => {
      const dir = sortOrder === 'asc' ? 1 : -1;
      return a[sortBy] > b[sortBy] ? dir : -dir;
    });

    const start      = (page - 1) * limit;
    const paginated  = sorted.slice(start, start + limit);
    const totalPages = Math.ceil(USERS.length / limit);

    // 7. FIELD FILTERING — never return fields the client doesn't need.
    //    Omit sensitive fields (e.g. passwordHash, ssn) explicitly.
    const safeUsers = paginated.map(({ id, name }) => ({ id, name }));

    res.json({
      data:       safeUsers,
      pagination: { page, limit, totalPages, totalItems: USERS.length },
    });

  } catch (err) {
    // Forward unexpected errors to the global error handler below.
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 8. 404 HANDLER — catch requests to undefined routes.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 9. GLOBAL ERROR HANDLER
//    Must have exactly 4 parameters so Express recognises it as an error handler.
//    Never expose internal error details (stack traces, DB messages) to clients.
// ---------------------------------------------------------------------------
app.use((err, req, res, _next) => { // eslint-disable-line no-unused-vars
  // Log the full error server-side for debugging.
  console.error(`[ERROR] ${new Date().toISOString()} ${req.method} ${req.path}`, err);

  const statusCode = err.status || err.statusCode || 500;

  // In production, hide implementation details from the response.
  const message = process.env.NODE_ENV === 'production'
    ? 'An unexpected error occurred.'
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ---------------------------------------------------------------------------
// SERVER STARTUP
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
  });
}

module.exports = app;

